{
  "name": "opencode-auto-continue",
  "version": "0.1.1",
  "description": "OpenCode plugin that automatically sends a continuation prompt when sessions go idle",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm && tsc --emitDeclarationOnly",
    "prepublishOnly": "bun run build",
    "typecheck": "tsc --noEmit",
    "dev": "bun build src/index.ts --outdir dist --target bun --format esm --watch"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/hjzccc/opencode-auto-continue.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "auto-continue"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.27"
  },
  "devDependencies": {
    "bun-types": "latest",
    "typescript": "^5.8.0"
  }
}

// @bun
// src/config.ts
import { existsSync, readFileSync } from "fs";
import { join } from "path";

// src/types.ts
var DEFAULT_CONFIG = {
  enabled: false,
  message: "continue",
  cooldown_ms: 1e4,
  max_consecutive: 5
};

// src/config.ts
var CONFIG_FILENAMES = [
  "auto-continue.json",
  "auto-continue.jsonc"
];
function stripJsonComments(text) {
  return text.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
}
function findConfigFile(directory) {
  for (const filename of CONFIG_FILENAMES) {
    const filePath = join(directory, ".opencode", filename);
    if (existsSync(filePath))
      return filePath;
  }
  return null;
}
function parseConfigFile(filePath) {
  const raw = readFileSync(filePath, "utf-8");
  const cleaned = stripJsonComments(raw);
  return JSON.parse(cleaned);
}
function loadConfig(directory) {
  const configPath = findConfigFile(directory);
  if (!configPath)
    return { ...DEFAULT_CONFIG };
  try {
    const parsed = parseConfigFile(configPath);
    return {
      enabled: parsed.enabled ?? DEFAULT_CONFIG.enabled,
      message: parsed.message ?? DEFAULT_CONFIG.message,
      cooldown_ms: parsed.cooldown_ms ?? DEFAULT_CONFIG.cooldown_ms,
      max_consecutive: parsed.max_consecutive ?? DEFAULT_CONFIG.max_consecutive
    };
  } catch {
    return { ...DEFAULT_CONFIG };
  }
}

// src/session-state.ts
function createSessionStateStore() {
  const states = new Map;
  function getState(sessionID) {
    const existing = states.get(sessionID);
    if (existing)
      return existing;
    const created = {
      lastInjectedAt: undefined,
      consecutiveCount: 0,
      lastAssistantMessageId: undefined,
      inFlight: false,
      deferredTimer: undefined
    };
    states.set(sessionID, created);
    return created;
  }
  function cleanup(sessionID) {
    const state = states.get(sessionID);
    if (state?.deferredTimer)
      clearTimeout(state.deferredTimer);
    states.delete(sessionID);
  }
  function resetConsecutive(sessionID) {
    const state = states.get(sessionID);
    if (state) {
      state.consecutiveCount = 0;
    }
  }
  return { getState, cleanup, resetConsecutive };
}

// src/idle-handler.ts
function resolveLastAssistantContext(messages) {
  for (let i = messages.length - 1;i >= 0; i--) {
    const info = messages[i].info;
    if (info?.role !== "assistant")
      continue;
    const providerID = info.model?.providerID ?? info.providerID;
    const modelID = info.model?.modelID ?? info.modelID;
    return {
      messageId: info.id,
      agent: info.agent,
      model: providerID && modelID ? { providerID, modelID } : undefined
    };
  }
  return { messageId: undefined, agent: undefined, model: undefined };
}
function resolveAgentFromUserMessages(messages) {
  for (let i = messages.length - 1;i >= 0; i--) {
    const info = messages[i].info;
    if (info?.role === "user" && info.agent)
      return info.agent;
  }
  return;
}
function hasRealUserMessageAfterLastContinue(messages, continueText) {
  for (let i = messages.length - 1;i >= 0; i--) {
    const msg = messages[i];
    if (msg.info?.role !== "user")
      continue;
    const text = (msg.parts ?? []).filter((p) => p.type === "text" && typeof p.text === "string").map((p) => p.text?.trim() ?? "").join("").toLowerCase();
    if (text === continueText.toLowerCase())
      return false;
    return true;
  }
  return false;
}
async function isSessionIdle(ctx, sessionID) {
  try {
    const response = await ctx.client.session.status({
      query: { directory: ctx.directory }
    });
    const map = response?.data ?? response ?? {};
    return !map[sessionID];
  } catch {
    return true;
  }
}
function createIdleHandler(args) {
  const { ctx, getConfig, sessionStateStore } = args;
  async function injectContinuation(sessionID) {
    const config = getConfig();
    if (!config.enabled)
      return;
    const state = sessionStateStore.getState(sessionID);
    if (state.inFlight)
      return;
    if (state.consecutiveCount >= config.max_consecutive)
      return;
    let messages = [];
    try {
      const response = await ctx.client.session.messages({
        path: { id: sessionID },
        query: { directory: ctx.directory }
      });
      messages = response?.data ?? response ?? [];
    } catch {
      return;
    }
    const assistantCtx = resolveLastAssistantContext(messages);
    if (!assistantCtx.messageId)
      return;
    if (state.lastAssistantMessageId === assistantCtx.messageId)
      return;
    if (hasRealUserMessageAfterLastContinue(messages, config.message)) {
      sessionStateStore.resetConsecutive(sessionID);
    }
    if (state.consecutiveCount >= config.max_consecutive)
      return;
    const agent = assistantCtx.agent ?? resolveAgentFromUserMessages(messages);
    if (!await isSessionIdle(ctx, sessionID))
      return;
    state.inFlight = true;
    try {
      const payload = {
        path: { id: sessionID },
        body: {
          ...agent ? { agent } : {},
          ...assistantCtx.model ? { model: assistantCtx.model } : {},
          parts: [{ type: "text", text: config.message }]
        },
        query: { directory: ctx.directory }
      };
      if (typeof ctx.client.session.promptAsync === "function") {
        await ctx.client.session.promptAsync(payload);
      } else {
        await ctx.client.session.prompt(payload);
      }
      state.lastAssistantMessageId = assistantCtx.messageId;
      state.consecutiveCount += 1;
      state.lastInjectedAt = Date.now();
    } catch {} finally {
      state.inFlight = false;
    }
  }
  return async ({ event }) => {
    if (event.type === "session.deleted") {
      const props2 = event.properties;
      const info = props2?.info;
      if (info?.id)
        sessionStateStore.cleanup(info.id);
      return;
    }
    if (event.type !== "session.idle")
      return;
    const config = getConfig();
    if (!config.enabled)
      return;
    const props = event.properties;
    const sessionID = props?.sessionID;
    if (!sessionID)
      return;
    const state = sessionStateStore.getState(sessionID);
    if (state.deferredTimer) {
      clearTimeout(state.deferredTimer);
      state.deferredTimer = undefined;
    }
    if (state.lastInjectedAt && Date.now() - state.lastInjectedAt < config.cooldown_ms) {
      const remaining = config.cooldown_ms - (Date.now() - state.lastInjectedAt);
      state.deferredTimer = setTimeout(() => {
        state.deferredTimer = undefined;
        injectContinuation(sessionID);
      }, remaining);
      return;
    }
    await injectContinuation(sessionID);
  };
}

// src/index.ts
var AutoContinuePlugin = async (ctx) => {
  const sessionStateStore = createSessionStateStore();
  const getConfig = () => loadConfig(ctx.directory);
  const idleHandler = createIdleHandler({ ctx, getConfig, sessionStateStore });
  return {
    event: idleHandler
  };
};
var src_default = AutoContinuePlugin;
export {
  src_default as default
};
